System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "last" => "last",
            "position" => "position",
            "name" => "name",
            "namespace-uri" => "namespace-uri",
            "local-name" => "local-name",
            "count" => "count",
            "id" => "id",
            "string" => "string",
            "concat" => "concat",
            "starts-with" => "starts-with",
            "contains" => "contains",
            "substring-before" => "substring-before",
            "substring-after" => "substring-after",
            "substring" => "substring",
            "string-length" => "string-length",
            "normalize-space" => "normalize-space",
            "translate" => "translate",
            "boolean" => "boolean",
            "not" => "not",
            "true" => "true",
            "false" => "false",
            "lang" => "lang",
            "number" => "number",
            "sum" => "sum",
            "floor" => "floor",
            "ceiling" => "ceiling",
            "round" => "round",
            _ => "default"
        };
    }
}
